if (seeAlsoH2) {
    const parent = seeAlsoH2.parentElement;
    const grandparent = parent.parentElement;
    const gpChildren = Array.from(grandparent.children);
    const parentIndex = gpChildren.indexOf(parent);

    // Find the div-col after the parent
    let seeAlsoDiv = null;
    for (let i = parentIndex + 1; i < gpChildren.length; i++) {
        const sibling = gpChildren[i];
        if (sibling.tagName === 'DIV' && sibling.className.includes('div-col')) {
            seeAlsoDiv = sibling;
            break;
        }
        // Stop if we hit another section or h2
        if (sibling.tagName === 'SECTION' || sibling.tagName === 'H2') break;
    }

    if (seeAlsoDiv) {
        const links = [];
        const anchors = seeAlsoDiv.querySelectorAll('a');
        anchors.forEach(a => {
            const title = a.getAttribute('title');
            const text = a.textContent.trim();
            const linkText = title || text;
            if (linkText && !linkText.startsWith('#') && linkText.length > 0) {
                links.push(linkText);
            }
        });

        return JSON.stringify({
            count: links.length,
            last: links.length > 0 ? links[links.length - 1] : null,
            all: links
        });
    }
}

return "Could not find div-col";
"""

